declare const tools: { mcp__engram__mem_search(args: {
  // Search across every project instead of the current one. When true, the project argument is ignored and results may come from any project. Useful for recalling decisions logged elsewhere when you don't know the project key.
  all_projects?: boolean;
  // Max results (default: 10, max: 20)
  limit?: number;
  // Token matching: "all" (default — every token must match, FTS5 AND) or "any" (any token matches — broader recall for multi-token queries). Any other value returns an error.
  match_mode?: string;
  // Filter by project name. Ignored when all_projects=true.
  project?: string;
  // Search query — natural language or keywords
  query: string;
  // Filter by scope: project (default) or personal
  scope?: string;
  // Filter by type: tool_use, file_change, command, file_read, search, manual, decision, architecture, bugfix, pattern
  type?: string;
}): Promise<CallToolResult>; };
